  --danger-color: #dc2626; /* Darkened from #ef4444 for contrast against white text */
  --danger-hover: #b91c1c; /* Darkened from #dc2626 */
  --btn-bg: #ffffff;
  --btn-hover: #f9fafb;
  --dialog-bg: #ffffff;
  --overlay-bg: rgba(0, 0, 0, 0.4);
