5.   const confirmBtn = document.getElementById('confirm-btn');
6. 
7.   // Open the dialog
8.   triggerBtn.addEventListener('click', () => {
9.     dialog.showModal();
10.   });
11. 
12.   // Close the dialog when clicking Cancel
13.   cancelBtn.addEventListener('click', () => {
14.     dialog.close();
15.   });
16. 
