<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Image Preview</title>
  <style>
    :root {
      --bg-color: #f3f4f6;
      --text-primary: #111827;
      --text-secondary: #4b5563;
      --border-color: #e5e7eb;
      --danger-color: #dc2626; /* Darkened for contrast against white text */
      --danger-hover: #b91c1c; 
      --btn-bg: #ffffff;
      --btn-hover: #f9fafb;
      --dialog-bg: #ffffff;
      --overlay-bg: rgba(0, 0, 0, 0.4);
      --focus-ring: #2563eb; /* Darkened for contrast */
    }

    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    body {
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background-color: var(--bg-color);
      color: var(--text-primary);
      display: flex;
      justify-content: center;
      align-items: center;
      min-height: 100vh;
      padding: 1rem;
    }

    /* Screen Reader Only Utility */
    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border-width: 0;
    }

    /* Main Preview Area */
    .preview-container {
      background: white;
      border-radius: 12px;
      box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
      overflow: hidden;
      max-width: 600px;
      width: 100%;
    }

    .image-wrapper {
      width: 100%;
      aspect-ratio: 4 / 3;
      overflow: hidden;
      background-color: var(--border-color);
    }

    .preview-image {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
    }

    .actions {
      padding: 1.5rem;
      display: flex;
      justify-content: flex-end;
      border-top: 1px solid var(--border-color);
    }

    /* Buttons */
    .btn {
      font-family: inherit;
      font-size: 0.875rem;
      font-weight: 500;
      padding: 0.625rem 1.25rem;
      border-radius: 6px;
      cursor: pointer;
      border: 1px solid var(--border-color);
      background-color: var(--btn-bg);
      color: var(--text-primary);
      transition: all 0.2s ease;
    }

    .btn:hover {
      background-color: var(--btn-hover);
    }

    .btn:focus-visible {
      outline: 2px solid var(--focus-ring);
      outline-offset: 2px;
    }

    .btn-danger {
      background-color: var(--danger-color);
      color: white;
      border-color: var(--danger-color);
    }

    .btn-danger:hover {
      background-color: var(--danger-hover);
      border-color: var(--danger-hover);
    }

    /* Dialog */
    dialog {
      margin: auto;
      padding: 0;
      border: none;
      border-radius: 12px;
      background: var(--dialog-bg);
      box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
      max-width: 400px;
      width: 90%;
    }

    /* Backdrop for modal */
    dialog::backdrop {
      background: var(--overlay-bg);
      backdrop-filter: blur(2px);
    }

    .dialog-content {
      padding: 1.5rem;
    }

    #dialog-title {
      font-size: 1.25rem;
      font-weight: 600;
      margin-bottom: 0.5rem;
    }

    #dialog-desc {
      font-size: 0.875rem;
      color: var(--text-secondary);
      line-height: 1.5;
      margin-bottom: 1.5rem;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 0.75rem;
    }
  </style>
</head>
<body>
  <main class="preview-container">
    <h1 class="sr-only">Image Preview</h1>
    <div class="image-wrapper">
      <img src="https://images.unsplash.com/photo-1682687220063-4742bd7fd538?q=80&w=800&auto=format&fit=crop" alt="A scenic mountain landscape" class="preview-image">
    </div>

    <div class="actions">
      <!-- Trigger button to open the modal dialog -->
      <button type="button" class="btn btn-danger trigger" id="delete-trigger">Delete Image</button>
    </div>
  </main>

  <!-- Native dialog element handles focus trap, background inertness, and return focus -->
  <dialog id="delete-dialog" role="alertdialog" aria-labelledby="dialog-title" aria-describedby="dialog-desc">
    <div class="dialog-content">
      <h2 id="dialog-title">Delete this image?</h2>
      <p id="dialog-desc">Are you sure you want to remove this image from your library? This action cannot be undone.</p>

      <div class="dialog-actions">
        <!-- Cancel gets focus by default so users don't accidentally delete -->
        <button type="button" class="btn btn-secondary" id="cancel-btn" autofocus>Cancel</button>
        <button type="button" class="btn btn-danger" id="confirm-btn">Delete</button>
      </div>
    </div>
  </dialog>

  <script>
    document.addEventListener('DOMContentLoaded', () => {
      const dialog = document.getElementById('delete-dialog');
      const triggerBtn = document.querySelector('.trigger');
      const cancelBtn = document.getElementById('cancel-btn');
      const confirmBtn = document.getElementById('confirm-btn');

      // Open the dialog
      triggerBtn.addEventListener('click', () => {
        dialog.showModal();
      });

      // Close the dialog when clicking Cancel
      cancelBtn.addEventListener('click', () => {
        dialog.close();
      });

      // Handle the confirm action
      confirmBtn.addEventListener('click', () => {
        // Perform delete logic here...
        console.log('Image deleted.');

        // Close the dialog
        dialog.close();

        // Note: If the trigger button or image was removed from the DOM here,
        // focus would need to be manually moved to a logical element since
        // the browser cannot return focus to an element that no longer exists.
      });

      // Optional: close when clicking on the dialog backdrop
      dialog.addEventListener('click', (event) => {
        const rect = dialog.getBoundingClientRect();
        const isInDialog = (
          rect.top <= event.clientY &&
          event.clientY <= rect.top + rect.height &&
          rect.left <= event.clientX &&
          event.clientX <= rect.left + rect.width
        );

        if (!isInDialog) {
          dialog.close();
        }
      });
    });
  </script>
</body>
</html>
